// QueryServer is the server API for Query service.
type QueryServer interface {
	// Params queries the module parameters.
	Params(context.Context, *QueryParamsRequest) (*QueryParamsResponse, error)
	// Epoch is the epoch in progress.
	Epoch(context.Context, *QueryEpochRequest) (*QueryEpochResponse, error)
	// Validator is one validator's book, live rate and derth supply.
	Validator(context.Context, *QueryValidatorRequest) (*QueryValidatorResponse, error)
	// Validators is every validator, paged: its book, its x/staking record and
	// whether it takes delegations. Everything a wallet needs to quote a
	// delegation, undelegation, redelegation or stake vote, read as one list
	// so that no query names the validator a wallet is about to act on (a
	// per-validator read ties the asking IP to an intent shortly before a
	// public msg). Pages walk x/staking's validators in its key order; the
	// last page (no next_key) also carries every book whose validator
	// x/staking has removed.
	Validators(context.Context, *QueryValidatorsRequest) (*QueryValidatorsResponse, error)
	// UnbondRecord is one epoch's private undelegation from a validator.
	UnbondRecord(context.Context, *QueryUnbondRecordRequest) (*QueryUnbondRecordResponse, error)
	// UnbondPayout is a queued undelegation payout (not found once paid).
	UnbondPayout(context.Context, *QueryUnbondPayoutRequest) (*QueryUnbondPayoutResponse, error)
	// GroundworksVote is one Groundworks vote, by id.
	GroundworksVote(context.Context, *QueryGroundworksVoteRequest) (*QueryGroundworksVoteResponse, error)
	// GroundworksVotes lists every Groundworks vote (a wallet finds its own by
	// its notes' tags; nothing asks about one tag).
	GroundworksVotes(context.Context, *QueryGroundworksVotesRequest) (*QueryGroundworksVotesResponse, error)
	// Snapshot is a proposal's stake-vote snapshot.
	Snapshot(context.Context, *QuerySnapshotRequest) (*QuerySnapshotResponse, error)
	// StakeTree is the stake note tree's size and latest recorded root.
	StakeTree(context.Context, *QueryStakeTreeRequest) (*QueryStakeTreeResponse, error)
	// StakeNullifier reports whether a stake nullifier (hex) is spent.
	StakeNullifier(context.Context, *QueryStakeNullifierRequest) (*QueryStakeNullifierResponse, error)
	// StakeNullifierTree pages the stake nullifier tree's values in insertion
	// order (leaf index start+1, start+2, ...; leaf 0 is the sentinel), with its
	// size and roots: what a wallet replays to build a vote's non-membership
	// witness at a snapshot (ProposalSnapshot.nf_size).
	StakeNullifierTree(context.Context, *QueryStakeNullifierTreeRequest) (*QueryStakeNullifierTreeResponse, error)
	// DebtTree pages the slash debt tree's rows in insertion order (leaf
	// index start+1, ...; leaf 0 is the sentinel) with its size and root, and
	// the label window: what a wallet needs to clear a label or vote a
	// labelled note.
	DebtTree(context.Context, *QueryDebtTreeRequest) (*QueryDebtTreeResponse, error)
	// Move is a private redelegation still open to slashing (not found once
	// its window closed), and its debt row if slashed.
	Move(context.Context, *QueryMoveRequest) (*QueryMoveResponse, error)
	// Vintages is one validator's stake vintages (v1.3.0): the current month,
	// the base vintage, each live vintage with its supply, asset denom and
	// retirement time, each retiring one, and (paged, oldest first) its
	// retired vintages not yet fully withdrawn, with their held payout's
	// state. For explorers: it names the validator, so wallets use
	// VintageBooks.
	Vintages(context.Context, *QueryVintagesRequest) (*QueryVintagesResponse, error)
	// VintageInfo is the chain's vintage clock: the current month, the base
	// vintage (the unsuffixed denom's month) and the next retirement time.
	// Names no validator.
	VintageInfo(context.Context, *QueryVintageInfoRequest) (*QueryVintageInfoResponse, error)
	// VintageBooks is every validator's stake vintages in one whole-chain
	// list, paged by (validator, vintage): live, retiring and retired (not
	// fully withdrawn) vintages with their supply and, when retired, the
	// held payout's state. Wallets read it whole, so that no query names the
	// validators they hold (Query/Vintages, for explorers, does).
	VintageBooks(context.Context, *QueryVintageBooksRequest) (*QueryVintageBooksResponse, error)
}

